// Bundles docs/privacy-policy.md and THIRD_PARTY_NOTICES.md into src/content/legal.ts so the
// About screen shows the same text as the repo (Metro can't import .md files).
// Run after editing either file: node scripts/build-legal.mjs  (a jest test fails if stale).
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => readFileSync(join(root, p), 'utf8');

export function legalSource() {
  return [
    '// Generated by scripts/build-legal.mjs from docs/privacy-policy.md and THIRD_PARTY_NOTICES.md.',
    '// Do not edit by hand.',
    '',
    `export const PRIVACY_POLICY_MD = ${JSON.stringify(read('docs/privacy-policy.md'))};`,
    '',
    `export const THIRD_PARTY_NOTICES_MD = ${JSON.stringify(read('THIRD_PARTY_NOTICES.md'))};`,
    '',
  ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(join(root, 'src/content/legal.ts'), legalSource());
  console.log('wrote src/content/legal.ts');
}
